15	/// The project's single `get_it` instance — exactly one DI container exists
16	/// (architecture spine). Every feature's `registerXFeature()` registers
17	/// through this same `sl`, never a second container.
18	final sl = GetIt.instance;
19	
20	/// Bootstraps core infrastructure: loads `.env`, then registers
21	/// `FlutterSecureStorage`, `Dio` (configured with the header + retry
22	/// interceptors) and `ApiClient` through `sl` — the `dio` +
23	/// `flutter_secure_storage` + `get_it` integration spike this story proves
24	/// before anything else is built on top of it.
25	Future<void> setupCoreDependencies() async {
26	  await dotenv.load(fileName: '.env');
27	
28	  final functionsBaseUrl = dotenv.get('FUNCTIONS_BASE_URL');
29	  final supabaseAnonKey = dotenv.get('SUPABASE_ANON_KEY');
30	
31	  sl.registerLazySingleton<FlutterSecureStorage>(
32	    () => const FlutterSecureStorage(),
33	  );
34	
35	  sl.registerLazySingleton<AccessTokenProvider>(
36	    () => SecureStorageAccessTokenProvider(sl<FlutterSecureStorage>()),
37	  );
38	
39	  sl.registerLazySingleton<UrlBuilder>(() => UrlBuilder(functionsBaseUrl));
40	
41	  // Story 1.5 — `dispose:` wires `SessionExpiryNotifier.dispose()` into
42	  // `get_it`'s own reset lifecycle, same rationale as `SessionRepository`'s
43	  // own registration below. Registration order here is cosmetic, not
44	  // load-bearing: `registerLazySingleton` only builds its instance on first
45	  // `sl<T>()` access, so `ApiClient`'s factory can resolve this dependency
46	  // correctly regardless of which of the two is registered first.
47	  sl.registerLazySingleton<SessionExpiryNotifier>(
48	    () => SessionExpiryNotifierImpl(),
49	    dispose: (notifier) => notifier.dispose(),
50	  );
51	
52	  sl.registerLazySingleton<Dio>(() {
53	    final dio = Dio(
54	      BaseOptions(
55	        // Design note (docs/input is silent on exact numbers): a stalled
56	        // connection must still fail instead of hanging indefinitely.
57	        connectTimeout: const Duration(seconds: 10),
58	        receiveTimeout: const Duration(seconds: 30),
59	        sendTimeout: const Duration(seconds: 30),
60	      ),
61	    );
62	    dio.interceptors.add(
63	      HeaderInterceptor(
64	        anonKey: supabaseAnonKey,
65	        accessTokenProvider: sl<AccessTokenProvider>(),
66	      ),
67	    );
68	    dio.interceptors.add(RetryInterceptor(dio));
69	    return dio;
70	  });
71	
72	  sl.registerLazySingleton<ApiClient>(
73	    () => ApiClient(
74	      dio: sl<Dio>(),
75	      urlBuilder: sl<UrlBuilder>(),
76	      sessionExpiryNotifier: sl<SessionExpiryNotifier>(),
77	    ),
78	  );
79	
80	  registerAuthFeature();
81	  registerVaultFeature();
82	}
83	
84	/// Test/teardown helper — resets the single `get_it` instance so each test
85	/// bootstraps its own clean registrations.
86	Future<void> resetCoreDependencies() => sl.reset();
