    17	/// Owns the one broadcast [VaultStatus] stream the epic's AD-14 seam
    18	/// requires. Covers the I/O matrix (spec-2-1 + spec-2-2 + spec-2-3):
    19	/// - biometrics succeed -> [VaultStatus.unlocked] emitted, `Right(unit)`.
    20	/// - biometrics fail/cancelled/unavailable (`authenticate()` returns
    21	///   `false`, or throws `LocalAuthException`, including any OS lockout) ->
    22	///   status stays [VaultStatus.locked], `Left(Failure.
    23	///   malformedResponse(...))` — every one of those cases routes the caller
    24	///   to [submitPin] next (spec-2-2), with no code-specific branch needed
    25	///   here since the generic catches below already cover lockout.
    26	/// - [submitPin], no PIN stored yet -> stores it, [VaultStatus.unlocked]
    27	///   emitted, `Right(unit)`.
    28	/// - [submitPin], stored PIN matches -> [VaultStatus.unlocked] emitted,
    29	///   `Right(unit)`.
    30	/// - [submitPin], stored PIN mismatch -> status stays locked, `Left(Failure.
    31	///   malformedResponse(...))`, always retryable (no attempt cap).
    32	/// - spec-2-3: backgrounded (`AppLifecycleState.paused`) for >= 5 minutes
    33	///   while [VaultStatus.unlocked], then resumed -> [VaultStatus.locked]
    34	///   emitted via [didChangeAppLifecycleState]; below that threshold, or
    35	///   while already locked, no emission at all.
    36	///
    37	/// Zero network calls anywhere in this class (Boundaries: "Vault makes zero
    38	/// network calls") and never produces [Failure.authInvalid] (Boundaries:
    39	/// reserved for password login) — every failure branch below maps only to
    40	/// [Failure.malformedResponse]. The PIN is compared as a plain string
    41	/// (Design Notes: `flutter_secure_storage` already encrypts at rest;
    42	/// `package:crypto` isn't a pinned dependency) stored under [_pinStorageKey]
    43	/// via the same [FlutterSecureStorage] instance
    44	/// `SecureStorageAccessTokenProvider` uses for the access/refresh tokens.
    45	class VaultRepositoryImpl
    46	    with WidgetsBindingObserver
    47	    implements VaultRepository {
    48	  VaultRepositoryImpl({
    49	    required LocalAuthentication localAuthentication,
    50	    required FlutterSecureStorage secureStorage,
    51	    DateTime Function() now = DateTime.now,
    52	  }) : _localAuthentication = localAuthentication,
    53	       _secureStorage = secureStorage,
    54	       _now = now {
    55	    // Story 2.3 — observes app-lifecycle transitions directly so idle
    56	    // re-lock works with zero DI changes and zero new VaultRepository
    57	    // methods. Removed in dispose() below. Safe only because
    58	    // `WidgetsFlutterBinding.ensureInitialized()` (or an equivalent, e.g.
    59	    // `TestWidgetsFlutterBinding.ensureInitialized()` in tests) must
    60	    // already have run before this constructor executes — true today
    61	    // because `get_it` constructs this lazily, well after `main()`'s own
    62	    // binding initialization.
    63	    //
    64	    // Review finding: `WidgetsBinding.instance` itself throws an opaque
    65	    // Flutter-internal assertion if no binding exists yet — caught here and
    66	    // rethrown with a message that names the actual root cause, so any
    67	    // future call site that breaks this ordering fails clearly instead of
    68	    // opaquely.
    69	    try {
    70	      WidgetsBinding.instance.addObserver(this);
    71	    } on FlutterError catch (error) {
    72	      throw StateError(
    73	        'VaultRepositoryImpl requires WidgetsFlutterBinding.ensureInitialized() '
    74	        '(or TestWidgetsFlutterBinding.ensureInitialized() in tests) to run '
    75	        'before construction. Original error: $error',
    76	      );
    77	    }
    78	  }
    79	
    80	  static const _pinStorageKey = 'vault_pin';
    81	
    82	  final LocalAuthentication _localAuthentication;
    83	  final FlutterSecureStorage _secureStorage;
    84	  final DateTime Function() _now;
    85	  final StreamController<VaultStatus> _statusController =
    86	      StreamController<VaultStatus>.broadcast();
    87	
    88	  /// Incremented at the start of every [submitPin] call. Review finding:
    89	  /// the UI's own `.timeout()` only stops it from *waiting* — the call
    90	  /// here keeps running — so a user-triggered retry after that UI timeout
    91	  /// could otherwise race a still-in-flight earlier call against the same
    92	  /// storage key, or let its stale result emit [VaultStatus.unlocked]
    93	  /// behind the newer attempt's back. A call whose captured generation no
    94	  /// longer matches this field by the time its [_secureStorage.read]
    95	  /// resolves is superseded and must not mutate storage or emit.
    96	  int _submitPinGeneration = 0;
    97	
    98	  /// Set on `AppLifecycleState.paused`, read and cleared on
    99	  /// `AppLifecycleState.resumed` (Boundaries: `inactive`/`hidden` are not
   100	  /// "backgrounded" on their own — only this pair bounds iOS's actual
   101	  /// background/foreground transition). `null` means either the app has
   102	  /// never been backgrounded, or the last `paused`->`resumed` cycle already
   103	  /// consumed it.
   104	  DateTime? _backgroundedAt;
   105	
   106	  /// The last status emitted. Starts at [VaultStatus.locked] — not
   107	  /// nullable, see [VaultStatus]'s own doc — so [currentStatus] is correct
   108	  /// synchronously from construction, with no async warm-up step.
   109	  VaultStatus _lastStatus = VaultStatus.locked;
   110	
   111	  @override
   112	  VaultStatus get currentStatus => _lastStatus;
   113	
   114	  @override
   115	  Stream<VaultStatus> get statusStream {
   116	    // Same `Stream.multi` replay-to-late-listeners rationale as
   117	    // `SessionRepositoryImpl.statusStream`: a listener that subscribes
   118	    // after construction (but before any [authenticate] call) still
   119	    // immediately sees the cached [_lastStatus] ([VaultStatus.locked])
   120	    // rather than nothing until the next emission.
   121	    return Stream<VaultStatus>.multi((controller) {
   122	      controller.add(_lastStatus);
   123	      final subscription = _statusController.stream.listen(
   124	        controller.add,
   125	        onError: controller.addError,
   126	        onDone: controller.close,
   127	      );
