   134	    // an in-flight `authenticate()` call — mirrors
   135	    // `SessionRepositoryImpl._emit`'s own guard.
   136	    if (_statusController.isClosed) {
   137	      return;
   138	    }
   139	    if (status == VaultStatus.unlocked) {
   140	      // Review finding: without this, a biometric/PIN call that resolves
   141	      // while the app is still backgrounded (persistAcrossBackgrounding:
   142	      // true covers exactly this) leaves the *original* `_backgroundedAt`
