   144	      // original timestamp, the idle check below immediately re-locks the
   145	      // vault the instant it was unlocked. Any unlock always starts the
   146	      // idle clock fresh instead.
   147	      _backgroundedAt = null;
   148	    }
   149	    _lastStatus = status;
   150	    _statusController.add(status);
   151	  }
   152	
   153	  @override
   154	  void didChangeAppLifecycleState(AppLifecycleState state) {
   155	    // Story 2.3's I/O & Edge-Case Matrix, exactly:
   156	    // - `paused` -> record the backgrounded timestamp (only meaningful read
   157	    //   on the next `resumed`).
   158	    // - `resumed` with no prior `paused` recorded -> no-op (e.g. the very
   159	    //   first lifecycle callback ever observed).
   160	    // - `resumed` with elapsed time < 5 minutes -> no-op, `currentStatus`
   161	    //   stays whatever it was.
   162	    // - `resumed` with elapsed time >= 5 minutes AND `currentStatus` is
   163	    //   currently `unlocked` -> emit `locked` exactly once; never
   164	    //   redundantly if already `locked` (no duplicate emission).
   165	    // `inactive`/`hidden` are intentionally ignored (Boundaries) — they
   166	    // don't bound the real background/foreground transition on their own.
   167	    if (state == AppLifecycleState.paused) {
   168	      // Review finding: `??=` (not `=`) — keeps the *earliest* timestamp if
   169	      // `paused` ever fires twice before a `resumed` consumes it, so a
   170	      // lifecycle quirk can't reset the idle clock to a later start and
   171	      // undercount real elapsed background time.
   172	      _backgroundedAt ??= _now();
   173	      return;
   174	    }
   175	    if (state == AppLifecycleState.resumed) {
   176	      final backgroundedAt = _backgroundedAt;
   177	      _backgroundedAt = null;
   178	      if (backgroundedAt == null) {
   179	        return;
   180	      }
   181	      final elapsed = _now().difference(backgroundedAt);
   182	      if (elapsed >= vaultIdleTimeout && _lastStatus == VaultStatus.unlocked) {
   183	        _emit(VaultStatus.locked);
   184	      }
   185	    }
   186	  }
   187	
   188	  @override
   189	  Future<Either<Failure, Unit>> authenticate() async {
   190	    try {
   191	      // `biometricOnly: true` (Boundaries/Design Notes) — never lets the
   192	      // OS's own device-passcode UI satisfy this call, which would bypass
   193	      // Cerne's own PIN screen (Story 2.2) entirely.
   194	      // `persistAcrossBackgrounding: true` so a backgrounding mid-prompt
   195	      // (e.g. an incoming call) retries on foreground instead of failing
   196	      // outright.
   197	      final success = await _localAuthentication.authenticate(
   198	        localizedReason: 'Autentique-se para acessar o Cerne',
   199	        biometricOnly: true,
   200	        persistAcrossBackgrounding: true,
   201	      );
