   207	      // stays `locked`; never `Failure.authInvalid` (Boundaries: reserved
   208	      // for password login).
   209	      return left(
   210	        const Failure.malformedResponse(
   211	          message: 'Biometric authentication was not successful',
   212	        ),
   213	      );
   214	    } on LocalAuthException catch (error) {
   215	      // Covers cancellation, no enrolled biometrics, hardware unavailable,
   216	      // etc. (RNF09: never let a platform exception escape unmapped).
   217	      return left(Failure.malformedResponse(message: error.toString()));
   218	    } catch (error) {
   219	      // Any other thrown platform exception (e.g. the plugin's channel
   220	      // itself failing) must never escape unmapped either (RNF09) — fail
   221	      // closed, same as the documented `LocalAuthException` branch above,
   222	      // mirroring `SessionRepositoryImpl.restoreSession()`'s own plain
   223	      // `catch`.
   224	      return left(Failure.malformedResponse(message: error.toString()));
   225	    }
   226	  }
   227	
   228	  @override
   229	  Future<Either<Failure, Unit>> submitPin(String pin) async {
   230	    final generation = ++_submitPinGeneration;
   231	    try {
   232	      final storedPin = await _secureStorage.read(key: _pinStorageKey);
   233	      if (generation != _submitPinGeneration) {
   234	        // A newer `submitPin` call started while this one was still
   235	        // awaiting `read` (e.g. the caller's own UI timed out and the user
   236	        // retried) — never let this superseded attempt write a possibly
   237	        // stale PIN or emit `unlocked` behind the newer attempt's back.
   238	        return left(
   239	          const Failure.malformedResponse(
   240	            message: 'Superseded by a newer PIN attempt',
   241	          ),
   242	        );
   243	      }
   244	      // No PIN-creation screen exists anywhere in `docs/input/` (Design
   245	      // Notes) — the first ever `submitPin` call sets the stored PIN
   246	      // instead of comparing against one.
   247	      if (storedPin == null) {
   248	        await _secureStorage.write(key: _pinStorageKey, value: pin);
   249	        _emit(VaultStatus.unlocked);
   250	        return right(unit);
   251	      }
   252	      if (storedPin == pin) {
   253	        _emit(VaultStatus.unlocked);
   254	        return right(unit);
   255	      }
   256	      // Mismatch — status stays `locked`, no attempt cap (Boundaries: "PIN
   257	      // has no attempt cap — always retryable"); never `Failure.authInvalid`
   258	      // (reserved for password login), same rationale as `authenticate()`.
   259	      return left(
   260	        const Failure.malformedResponse(
   261	          message: 'PIN did not match the stored PIN',
   262	        ),
   263	      );
   264	    } catch (error) {
   265	      // A thrown platform exception from the secure-storage channel must
   266	      // never escape unmapped either (RNF09) — fail closed, same as
   267	      // `authenticate()`'s own plain `catch`.
   268	      return left(Failure.malformedResponse(message: error.toString()));
   269	    }
   270	  }
   271	
   272	  @override
   273	  Future<void> dispose() async {
   274	    WidgetsBinding.instance.removeObserver(this);
   275	    await _statusController.close();
   276	  }
   277	}
